<?php $laudo=$laudo??(object)array();$settings=$settings??array(); ?><style>body{font-family:helvetica;font-size:9px;color:#222}.cover{text-align:center;padding-top:90px}.cover h1{font-size:24px;color:<?php echo esc($settings['report_primary_color']??'#2d6ca2'); ?>}.section{page-break-inside:avoid;margin-top:12px}.section h2{font-size:14px;background-color:<?php echo esc($settings['report_primary_color']??'#2d6ca2'); ?>;color:#fff;padding:6px}.meta{width:100%;border-collapse:collapse}.meta td,.data th,.data td{border:1px solid #bbb;padding:4px}.data{width:100%;border-collapse:collapse}.data th{background-color:#eee}.muted{color:#666}.photo{width:45%;height:70px;object-fit:contain}</style><div class="cover"><h1><?php echo esc($report_kind??'Relatório técnico'); ?></h1><h2><?php echo esc($laudo->number??'-'); ?></h2><h3><?php echo esc($laudo->title??'-'); ?></h3><p><?php echo esc($laudo->client_name??'-'); ?></p><p><?php echo $final?'VERSÃO FINAL':'RASCUNHO — PRÉ-VISUALIZAÇÃO'; ?> · v<?php echo (int)$version; ?></p><p><?php echo esc($generated_at); ?></p></div><div class="section"><h2>Identificação</h2><table class="meta"><tr><td><b>Cliente</b><br><?php echo esc($laudo->client_name??'-'); ?></td><td><b>Tipo</b><br><?php echo esc($laudo->type_name??'-'); ?></td></tr><tr><td><b>Endereço</b><br><?php echo nl2br(esc($laudo->inspection_address??'-')); ?></td><td><b>Responsável</b><br><?php echo esc($laudo->technical_responsible_name??'-'); ?></td></tr></table></div><?php foreach(array('objective'=>'Objetivo','scope'=>'Escopo','installation_description'=>'Descrição da instalação','conclusion'=>'Conclusão') as $field=>$label){ ?><div class="section"><h2><?php echo $label; ?></h2><p><?php echo nl2br(esc($laudo->{$field}??'-')); ?></p></div><?php } ?><div class="section"><h2>Resumo da vistoria</h2><p>Status: <?php echo esc($laudo->status??'-'); ?> · Data: <?php echo esc($laudo->inspection_date??'-'); ?></p></div><div class="section"><h2>Medições</h2><?php if($measurements){ ?><table class="data"><thead><tr><th>Tipo</th><th>Ponto</th><th>Valor</th><th>Unidade</th><th>Resultado</th><th>Data</th></tr></thead><tbody><?php foreach($measurements as $m){ ?><tr><td><?php echo esc($m->measurement_type?:$m->name); ?></td><td><?php echo esc($m->point_identifier?:'-'); ?></td><td><?php echo esc($m->value); ?></td><td><?php echo esc($m->unit); ?></td><td><?php echo esc($m->result_classification); ?></td><td><?php echo esc($m->measured_at); ?></td></tr><?php } ?></tbody></table><?php }else{ ?><p class="muted">Nenhuma medição registrada.</p><?php } ?></div><div class="section"><h2>Não conformidades</h2><?php if($nonconformities){ ?><table class="data"><thead><tr><th>Código</th><th>Descrição</th><th>Criticidade</th><th>Recomendação</th><th>Prazo</th></tr></thead><tbody><?php foreach($nonconformities as $n){ ?><tr><td><?php echo esc($n->code); ?></td><td><?php echo nl2br(esc($n->description)); ?></td><td><?php echo esc($n->severity); ?></td><td><?php echo nl2br(esc($n->recommendation)); ?></td><td><?php echo esc($n->due_date); ?></td></tr><?php } ?></tbody></table><?php }else{ ?><p class="muted">Nenhuma não conformidade registrada.</p><?php } ?></div><div class="section"><h2>Registro fotográfico</h2><?php if($photos){foreach($photos as $photo){ ?><div style="display:inline-block;width:48%;vertical-align:top"><p><b><?php echo esc($photo->title?:'Fotografia'); ?></b><br><?php echo esc($photo->caption); ?></p></div><?php }}else{ ?><p class="muted">Nenhuma fotografia registrada.</p><?php } ?></div><div class="section"><h2>Assinaturas</h2><p style="margin-top:40px">__________________________________<br><?php echo esc($laudo->technical_responsible_name??'Responsável técnico'); ?></p></div><div class="section"><h2>Anexos</h2><p class="muted">Anexos vinculados ao laudo, quando existentes.</p></div>
